const SYSTEM = "Voc\u00ea escreve para o Instagram de uma cl\u00ednica veterin\u00e1ria especializada em felinos (gatos), no Brasil. Tom: acolhedor, claro e respons\u00e1vel, para tutores leigos. Portugu\u00eas do Brasil. No m\u00e1ximo 2 emojis. Regras: nunca diagnostique nem prescreva; nunca indique medicamentos ou doses (v\u00e1rios rem\u00e9dios humanos s\u00e3o perigosos para gatos); n\u00e3o prometa cura; n\u00e3o cite pre\u00e7os nem promo\u00e7\u00f5es; n\u00e3o critique outros profissionais. Em sinais de emerg\u00eancia (dificuldade para respirar, tentativas de urinar sem sucesso, convuls\u00e3o, sangramento, v\u00f4mitos repetidos, apatia intensa, suspeita de intoxica\u00e7\u00e3o), oriente atendimento veterin\u00e1rio imediato. Termine com um convite suave para agendar consulta. Responda SOMENTE com um objeto JSON v\u00e1lido, sem texto fora dele, com as chaves: \"legenda\" (legenda completa com 5 a 8 hashtags no final), \"roteiro\" (se formato=reels: roteiro falado de 30 a 45 segundos com cenas; se carrossel: texto de 6 a 8 slides, um por linha, come\u00e7ando por 'Slide 1:'; se imagem: texto curto para a arte), \"sugestao_visual\" (descri\u00e7\u00e3o da imagem ou do v\u00eddeo a produzir).";
const temas = ["Bolas de pelo: quando \u00e9 normal e quando \u00e9 sinal de alerta", "Meu gato bebe pouca \u00e1gua: como estimular a hidrata\u00e7\u00e3o", "Doen\u00e7a renal cr\u00f4nica em gatos: sinais precoces", "Castra\u00e7\u00e3o de gatos: benef\u00edcios e mitos", "Vacinas essenciais para gatos (V4/V5 e FeLV): quando fazer", "Estresse felino e enriquecimento ambiental dentro de casa", "Obstru\u00e7\u00e3o urin\u00e1ria em gatos: por que \u00e9 uma emerg\u00eancia", "Cuidados com gatos idosos: o que muda depois dos 10 anos", "Sa\u00fade bucal: gengivite e doen\u00e7a periodontal em gatos", "Plantas t\u00f3xicas para gatos, como o l\u00edrio: o que evitar em casa", "Mitos e verdades sobre gatos", "Como levar o gato ao veterin\u00e1rio sem estresse (caixa de transporte)", "Chegada de um filhote: primeiros cuidados e primeira consulta", "Obesidade felina: como perceber e por que importa"];

const formatos = ['carrossel', 'reels', 'imagem'];
const sd = $getWorkflowStaticData('global');
const i = sd.i || 0;
const out = [];
for (let k = 0; k < 3; k++) {
  const tema = temas[(i + k) % temas.length];
  const formato = formatos[k % formatos.length];
  const body = {
    model: "claude-sonnet-5-5",
    max_tokens: 1500,
    system: SYSTEM,
    messages: [{ role: 'user', content: `Tema: ${tema}\nFormato: ${formato}\nCrie o conteúdo.` }]
  };
  out.push({ json: { tema, formato, body } });
}
sd.i = (i + 3) % temas.length;
return out;

const items = $input.all();
const out = [];
items.forEach((it, i) => {
  const ctx = $('Escolher temas').all()[i].json;
  let d;
  try {
    const t = it.json.content[0].text;
    d = JSON.parse(t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1));
  } catch (e) {
    d = { legenda: '(erro ao interpretar a resposta da IA - gere novamente)', roteiro: '', sugestao_visual: '' };
  }
  out.push({ json: {
    id: Date.now() + '-' + i,
    data_criacao: new Date().toISOString(),
    tema: ctx.tema,
    formato: ctx.formato,
    legenda: d.legenda || '',
    roteiro: typeof d.roteiro === 'string' ? d.roteiro : JSON.stringify(d.roteiro || ''),
    sugestao_visual: d.sugestao_visual || '',
    image_url: '',
    status: 'rascunho'
  }});
});
return out;
